#requires -Version 7.0
[CmdletBinding()]
param(
    [string]$ProjectPath = 'F:\srv\vibecoding',
    [switch]$Setup,
    [switch]$Once,
    [switch]$InstallStartup,
    [switch]$RemoveStartup,
    [ValidateRange(2,3600)][int]$PollSeconds = 5,
    [ValidateRange(5,3600)][int]$QuietSeconds = 15
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$Root = (Resolve-Path -LiteralPath $ProjectPath).Path.TrimEnd('\','/')
$GitPath = (Get-Command git -ErrorAction Stop).Source
$GitDir = Join-Path $Root '.git'
$ConfigPath = Join-Path $GitDir 'bridge-sync.json'
$InstalledScript = Join-Path $Root 'Sincronizar-GitHub.ps1'
$ShortcutPath = Join-Path ([Environment]::GetFolderPath('Startup')) 'TheBridge-GitHub-Sync.lnk'
$env:GIT_TERMINAL_PROMPT = '0'
$env:GCM_INTERACTIVE = 'never'
$Utf8 = [Text.UTF8Encoding]::new($false)

function Invoke-Program {
    param([string]$Exe,[string[]]$Arguments,[int[]]$OkCodes = @(0))
    $psi = [Diagnostics.ProcessStartInfo]::new()
    $psi.FileName = $Exe
    $psi.WorkingDirectory = $Root
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.StandardOutputEncoding = $Utf8
    $psi.StandardErrorEncoding = $Utf8
    foreach ($a in $Arguments) { [void]$psi.ArgumentList.Add($a) }
    $proc = [Diagnostics.Process]::new()
    $proc.StartInfo = $psi
    try {
        [void]$proc.Start()
        $stdout = $proc.StandardOutput.ReadToEndAsync()
        $stderr = $proc.StandardError.ReadToEndAsync()
        if (-not $proc.WaitForExit(1800000)) {
            $proc.Kill($true)
            throw 'Comando excedeu 1800 segundos; sincronizacao nao concluida.'
        }
        $text = $stdout.GetAwaiter().GetResult()
        $err = $stderr.GetAwaiter().GetResult()
        if ($proc.ExitCode -notin $OkCodes) {
            throw "Comando falhou (codigo $($proc.ExitCode)): $err $text"
        }
        return [pscustomobject]@{ Code=$proc.ExitCode; Text=$text.TrimEnd([char[]]"`r`n"); ErrorText=$err }
    } finally { $proc.Dispose() }
}
function G {
    param([string[]]$Arguments,[int[]]$OkCodes=@(0))
    return Invoke-Program -Exe $GitPath -Arguments (@('-C',$Root,'-c','core.quotepath=false') + $Arguments) -OkCodes $OkCodes
}
function Say([string]$Message) {
    $line = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] $Message"
    Write-Host $line
    if (Test-Path -LiteralPath $GitDir -PathType Container) {
        Add-Content -LiteralPath (Join-Path $GitDir 'bridge-sync.log') -Value $line -Encoding utf8
    }
}
function Save-Config {
    [IO.File]::WriteAllText($ConfigPath,($script:Cfg | ConvertTo-Json),$Utf8)
}
function Assert-Branch {
    $branch = (G -Arguments @('branch','--show-current')).Text
    if ($branch -ne 'main') { throw "STOP: branch atual '$branch', esperada 'main'. Nenhuma troca foi feita." }
    $remote = (G -Arguments @('remote','get-url','origin')).Text
    if ($remote -ne $script:Cfg.Remote) { throw 'STOP: origin mudou. Revise a configuracao manualmente.' }
    foreach ($operation in @('MERGE_HEAD','CHERRY_PICK_HEAD','REVERT_HEAD','rebase-merge','rebase-apply','index.lock')) {
        if (Test-Path -LiteralPath (Join-Path $GitDir $operation)) { throw "STOP: Git ocupado ou operacao pendente: $operation" }
    }
}
function Assert-RemoteSafe {
    $null = G -Arguments @('fetch','origin')
    $ref = G -Arguments @('show-ref','--verify','--quiet','refs/remotes/origin/main') -OkCodes @(0,1)
    if ($ref.Code -eq 1) {
        $allRefs = (G -Arguments @('ls-remote','origin')).Text
        if ($script:Cfg.AllowEmptyRemote -and [string]::IsNullOrWhiteSpace($allRefs)) { return }
        throw 'STOP: origin/main ausente ou repositorio remoto inesperado. Nao recriei a branch.'
    }
    $ancestor = G -Arguments @('merge-base','--is-ancestor','refs/remotes/origin/main','HEAD') -OkCodes @(0,1)
    if ($ancestor.Code -ne 0) {
        throw 'STOP: GitHub tem alteracoes nao integradas localmente. Nao fiz pull, merge, rebase ou force. Reconcilie manualmente.'
    }
}
function Stage-And-Check {
    $null = G -Arguments @('add','--all','--','.')
    $staged = (G -Arguments @('ls-files','--stage')).Text
    if ($staged -match '(?m)^160000 ') { throw 'STOP: repositorio Git interno/submodulo encontrado. Confira a estrutura antes de enviar.' }
    $names = (G -Arguments @('ls-files','-z')).Text.Split([char]0,[StringSplitOptions]::RemoveEmptyEntries)
    foreach ($name in $names) {
        if ($name -match '(?i)(^|/)(\.env($|\.)|credentials[^/]*|secrets?\.[^/]*|id_rsa[^/]*|id_ed25519[^/]*)' -or $name -match '(?i)\.(pem|key|pfx|p12)$') {
            throw "STOP: arquivo com nome potencialmente sensivel no indice: $name. Nao foi enviado; revise gitignore e indice manualmente."
        }
        $path = Join-Path $Root $name
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            $item = Get-Item -LiteralPath $path
            if ($item.Length -ge 95MB) { throw "STOP: arquivo >=95 MiB: $name. Revise armazenamento/LFS antes de enviar." }
        }
    }
    return (G -Arguments @('write-tree')).Text
}
function Push-Current {
    Assert-Branch
    Assert-RemoteSafe
    $null = G -Arguments @('push','--set-upstream','origin','HEAD:refs/heads/main')
    $script:Cfg.AllowEmptyRemote = $false
    Save-Config
    $sha = (G -Arguments @('rev-parse','--short','HEAD')).Text
    Say "GitHub atualizado: main @ $sha"
}

if ($RemoveStartup) {
    if (Test-Path -LiteralPath $ShortcutPath) { Remove-Item -LiteralPath $ShortcutPath }
    Write-Host 'Inicio automatico removido. Feche outra janela do sincronizador, se estiver aberta.'
    return
}
$rootBytes = [Text.Encoding]::UTF8.GetBytes($Root.ToLowerInvariant())
$hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($rootBytes)).Substring(0,20)
$mutex = [Threading.Mutex]::new($false,"Local\TheBridgeGitSync-$hash")
$owned = $false
try {
    try { $owned = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $owned = $true }
    if (-not $owned) { throw 'Ja existe um sincronizador ativo para essa pasta.' }

    if ($Setup -and -not (Test-Path -LiteralPath $ConfigPath)) {
        if (Test-Path -LiteralPath $GitDir) { throw 'A pasta ja tem .git e nao foi configurada por este script. Nao alterei esse repositorio. A configuracao precisa ser adaptada ao Git existente.' }
        $inside = G -Arguments @('rev-parse','--show-toplevel') -OkCodes @(0,128)
        if ($inside.Code -eq 0) { throw 'A pasta esta dentro de outro repositorio Git. Nao criei repositorio aninhado.' }
        $GhPath = (Get-Command gh -ErrorAction Stop).Source
        $null = Invoke-Program -Exe $GhPath -Arguments @('auth','status','--hostname','github.com')
        $null = Invoke-Program -Exe $GhPath -Arguments @('auth','setup-git','--hostname','github.com')
        $url = (Read-Host 'Cole a URL HTTPS do repositorio GitHub VAZIO, sem token').Trim()
        $uri = $null
        if (-not [Uri]::TryCreate($url,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -ne 'https' -or $uri.Host -ne 'github.com' -or $uri.UserInfo -or $uri.Query -or $uri.Fragment) {
            throw 'Use uma URL HTTPS simples do github.com, sem credenciais, query ou fragmento.'
        }
        $slug = $uri.AbsolutePath.Trim('/'); $slug = $slug -replace '\.git$',''
        if ($slug -notmatch '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$') { throw 'URL precisa apontar para DONO/REPOSITORIO, nao arquivo ou branch.' }
        $remote = "https://github.com/$slug.git"
        $infoText = (Invoke-Program -Exe $GhPath -Arguments @('repo','view',$slug,'--json','nameWithOwner,isPrivate')).Text
        $info = $infoText | ConvertFrom-Json
        if (-not $info.isPrivate) {
            Write-Warning 'REPOSITORIO PUBLICO: toda pessoa podera ler os arquivos enviados.'
            if ((Read-Host 'Para aceitar publicacao publica digite PUBLICO') -cne 'PUBLICO') { throw 'Cancelado.' }
        }
        $refs = (G -Arguments @('ls-remote',$remote)).Text
        if (-not [string]::IsNullOrWhiteSpace($refs)) { throw 'O repositorio remoto nao esta vazio. Nao combinei historicos. Use um repositorio vazio ou solicite adaptacao.' }
        Write-Warning "Sera versionada a pasta inteira: $Root. Nomes sensiveis comuns serao ignorados, mas isso NAO e auditoria de segredos. Confira todo o conteudo."
        if ((Read-Host 'Para preparar arquivos locais e revisar o primeiro envio, digite PREPARAR') -cne 'PREPARAR') { throw 'Cancelado.' }
        $null = G -Arguments @('init','-b','main')
        $null = G -Arguments @('remote','add','origin',$remote)
        foreach ($key in @('user.name','user.email')) {
            $value = (G -Arguments @('config','--get',$key) -OkCodes @(0,1)).Text
            if ([string]::IsNullOrWhiteSpace($value)) {
                $value = (Read-Host "Informe $key (somente para este repositorio; email pode ser noreply do GitHub)").Trim()
                if ([string]::IsNullOrWhiteSpace($value)) { throw "Valor obrigatorio: $key" }
                $null = G -Arguments @('config','--local',$key,$value)
            }
        }
        $script:Cfg = [pscustomobject]@{ Version=1; Remote=$remote; Branch='main'; AllowEmptyRemote=$true }
        Save-Config
        if ($PSCommandPath -ne $InstalledScript) {
            if (Test-Path -LiteralPath $InstalledScript) { throw 'Ja existe Sincronizar-GitHub.ps1 no destino. Nao sobrescrevi.' }
            Copy-Item -LiteralPath $PSCommandPath -Destination $InstalledScript
        }
        $Templates = @{
            'README.md' = ''
            'ESTADO-ATUAL.md' = ''
            'DECISOES.md' = ''
            'TESTES.md' = ''
        }
        foreach ($name in $Templates.Keys) {
            $destination = Join-Path $Root $name
            $content = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Templates[$name]))
            if (-not (Test-Path -LiteralPath $destination)) {
                [IO.File]::WriteAllText($destination,$content,$Utf8)
            } elseif ($name -eq 'README.md') {
                $proposal = Join-Path $Root 'README-IA-PROPOSTO.md'
                if (-not (Test-Path -LiteralPath $proposal)) { [IO.File]::WriteAllText($proposal,$content,$Utf8) }
                Write-Warning 'README existente preservado. Integre README-IA-PROPOSTO.md ao README antes de usar as instrucoes novas.'
            }
        }
        if (Get-ChildItem -LiteralPath (Join-Path $Root '.github') -Filter 'README*' -File -ErrorAction SilentlyContinue) {
            Write-Warning 'Ha README em .github, que pode ter prioridade sobre README da raiz na pagina do GitHub.'
        }
        $ignore = @'

# BEGIN bridge-github-sync: nomes sensiveis e temporarios comuns
.env
.env.*
*.pem
*.key
*.pfx
*.p12
id_rsa*
id_ed25519*
credentials*
secret.*
secrets.*
*.tmp
*.swp
*.log
.DS_Store
Thumbs.db
# END bridge-github-sync
'@
        $ignorePath = Join-Path $Root '.gitignore'
        $existing = if (Test-Path -LiteralPath $ignorePath) { [IO.File]::ReadAllText($ignorePath) } else { '' }
        if ($existing -notlike '*BEGIN bridge-github-sync*') { [IO.File]::WriteAllText($ignorePath,$existing + "`n" + $ignore + "`n",$Utf8) }
        $launcher = "@echo off`r`npwsh.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File `"%~dp0Sincronizar-GitHub.ps1`" -ProjectPath `"$Root`"`r`npause`r`n"
        $launchPath = Join-Path $Root 'Iniciar-Sync.cmd'
        if (-not (Test-Path -LiteralPath $launchPath)) { [IO.File]::WriteAllText($launchPath,$launcher,[Text.Encoding]::ASCII) }
        $null = Stage-And-Check
        Write-Host "`nARQUIVOS DO PRIMEIRO COMMIT:"
        Write-Host (G -Arguments @('status','--short')).Text
        Write-Host "`nRESUMO:"
        Write-Host (G -Arguments @('diff','--cached','--stat')).Text
        Write-Warning 'O ignore filtra nomes; senhas/tokens dentro de .yml, .json, .sk etc. NAO sao detectados. Revise antes de confirmar.'
        if ((Read-Host 'Para autorizar primeiro commit/envio e os envios automaticos posteriores desta pasta, digite PUBLICAR') -cne 'PUBLICAR') {
            throw 'Cancelado antes do primeiro envio. Arquivos locais e indice foram preparados. Antes de retomar, revise/remova o que nao pode ser enviado.'
        }
        $script:Cfg | Add-Member -NotePropertyName Enabled -NotePropertyValue $true
        Save-Config
        $null = G -Arguments @('commit','-m','Configura sincronizacao e documentacao inicial do projeto')
        Push-Current
    }
    if (-not (Test-Path -LiteralPath $ConfigPath)) { throw 'Ainda nao configurado. Execute uma vez com -Setup.' }
    $script:Cfg = Get-Content -LiteralPath $ConfigPath -Raw | ConvertFrom-Json
    if (-not $script:Cfg.PSObject.Properties['Enabled'] -or -not $script:Cfg.Enabled) {
        throw 'Primeiro envio nao foi autorizado/concluido. Configuracao parcial preservada: nao continue automaticamente. Revise com ajuda antes de habilitar.'
    }
    if ($InstallStartup) {
        $shell = New-Object -ComObject WScript.Shell
        $shortcut = $shell.CreateShortcut($ShortcutPath)
        $shortcut.TargetPath = (Get-Command pwsh).Source
        $shortcut.Arguments = "-NoLogo -NoProfile -ExecutionPolicy Bypass -File `"$InstalledScript`" -ProjectPath `"$Root`""
        $shortcut.WorkingDirectory = $Root
        $shortcut.WindowStyle = 7
        $shortcut.Save()
        Say 'Inicio automatico configurado para o proximo login do usuario (janela minimizada).'
    }
    Say "Sincronizador ativo em $Root. Ctrl+C encerra; salvar/excluir/renomear pode gerar commit remoto."
    $lastTree = ''; $lastChanged = Get-Date; $lastPushCheck = [datetime]::MinValue
    do {
        try {
            Assert-Branch
            $tree = Stage-And-Check
            $headResult = G -Arguments @('rev-parse','--verify','HEAD^{tree}') -OkCodes @(0,128)
            if ($headResult.Code -ne 0) { throw 'STOP: nao existe commit inicial. Configuracao incompleta.' }
            $headTree = $headResult.Text
            if ($Once -and $tree -ne $headTree) {
                Say "Modo -Once: aguardando $QuietSeconds segundos para confirmar estabilidade."
                Start-Sleep -Seconds $QuietSeconds
                if ((Stage-And-Check) -ne $tree) { throw 'STOP: arquivos mudaram durante a espera. Nenhum commit foi criado neste ciclo; tente novamente.' }
                Assert-RemoteSafe
                $null = G -Arguments @('commit','-m',"Autosave local $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') [NAO VALIDADO]")
                Push-Current
            } elseif ($tree -ne $headTree) {
                if ($tree -ne $lastTree) { $lastTree=$tree; $lastChanged=Get-Date }
                if (((Get-Date)-$lastChanged).TotalSeconds -ge $QuietSeconds) {
                    Assert-RemoteSafe
                    if ((Stage-And-Check) -ne $tree) { $lastTree=''; continue }
                    $null = G -Arguments @('commit','-m',"Autosave local $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') [NAO VALIDADO]")
                    Push-Current
                    $lastTree=''; $lastPushCheck=Get-Date
                }
            } elseif ($Once -or ((Get-Date)-$lastPushCheck).TotalSeconds -ge 60) {
                Assert-RemoteSafe
                $remoteSha = G -Arguments @('rev-parse','--verify','refs/remotes/origin/main') -OkCodes @(0,128)
                $localSha = (G -Arguments @('rev-parse','HEAD')).Text
                if ($remoteSha.Code -ne 0 -or $remoteSha.Text -ne $localSha) { Push-Current }
                $lastPushCheck=Get-Date
            }
        } catch {
            Say $_.Exception.Message
            if ($Once -or $_.Exception.Message.StartsWith('STOP:')) { throw }
            Say 'Falha temporaria: nova tentativa em 60 segundos. Nao houve force ou pull automatico.'
            Start-Sleep -Seconds 60
        }
        if (-not $Once) { Start-Sleep -Seconds $PollSeconds }
    } while (-not $Once)
} catch {
    Write-Host "`nSINCRONIZACAO INTERROMPIDA: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host 'Nao use force/reset para contornar. Confira o erro e preserve os arquivos locais.'
    exit 1
} finally {
    if ($owned) { $mutex.ReleaseMutex() }
    $mutex.Dispose()
}
